dict.string:
function check_called_post_startup() { mkdir -p "${alfred_workflow_data}"
local check_file="${alfred_workflow_data}/check_called_post_startup"
local boot_time=$(sysctl -n kern.boottime | awk '{print $4}' | sed 's/,//')
if [[ -f "$check_file" ]]; then local file_mod_time=$(stat -f "%m" "$check_file")
if (( file_mod_time > boot_time )); then echo -n "true" return 0 else touch "$check_file" echo -n "false" return 1 fi else touch "$check_file" echo -n "false" return 1 fi }
check_called_post_startup
